UPDATE "posts" SET "body" = jsonb_build_array(jsonb_build_object('type', 'note', 'title', 'Đã có cập nhật đường chạy', 'text',
  $j$Ngày 11/11/2026 ban tổ chức đã cập nhật sơ đồ đường chạy 10 km và 21 km: xuất phát – về đích chuyển về Cầu Rạch Sa Nhiên. Xem [bài cập nhật mới nhất](/tin-tuc/sa-dec-flower-half-marathon-2026-cap-nhat-duong-chay).$j$)) || "body",
  "updated_at" = now()
